<script setup>
import GettingStarted from '../GettingStarted.vue'
import OwnerAccess from './OwnerAccess.vue'
import SubscriptionAdmin from './SubscriptionAdmin.vue'
import BrandLogo from '../BrandLogo.vue'
import {ref,computed,onMounted} from 'vue'
import Icon from '../Icon.vue'
import Wallet from '../commerce/Wallet.vue'
import OnboardingSettings from './OnboardingSettings.vue'
import {request} from './client'
const props=defineProps({session:Object})
const tab=ref('Overview'),summary=ref({}),pending=ref([]),error=ref(''),busy=ref(false),note=ref(''),search=ref(''),reviews=ref({}),loaded=ref(false)
const tabs=['Overview','Subscriptions','Verification','Payouts','Signup & privacy','Admin access','Platform guide']
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
const filtered=computed(()=>pending.value.filter(p=>[p.display_name,p.username,p.kind,p.country].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())))
const actions=[{tab:'Subscriptions',icon:'Receipt',title:'Subscriptions & invoices',text:'Review plans, billing periods and bank payments.'},{tab:'Verification',icon:'BadgeCheck',title:'Provider approvals',text:'Review teacher and institute applications.'},{tab:'Payouts',icon:'Wallet',title:'Payout requests',text:'Review provider withdrawals and their status.'},{tab:'Signup & privacy',icon:'Settings2',title:'Signup & privacy',text:'Manage onboarding and privacy settings.'},{tab:'Admin access',icon:'ShieldCheck',title:'Admin access',text:'Manage who can administer the platform.'}]
const labels={students:'Active students',teachers:'Verified teachers',institutes:'Verified institutes',pending_profiles:'Awaiting verification',pending_payouts:'Pending payouts'}
function draft(p){return reviews.value[p.name] ||= {reason:'',workspace:''}}
async function refresh(){[summary.value,pending.value]=await Promise.all([request('portal_session','overview'),request('profiles','pending')]);loaded.value=true}
async function verify(p,decision){await run(async()=>{await request('profiles','review',{profile:p.name,decision,reason:draft(p).reason,workspace:draft(p).workspace});delete reviews.value[p.name];await refresh();note.value='Verification decision saved.'})}
onMounted(()=>run(refresh))
</script>
<template><div class="owner-shell"><aside><a class="entry-brand" href="#"><BrandLogo/></a><span class="owner-tag">SUPER ADMIN</span><nav><button v-for="name in tabs" :key="name" :aria-current="tab===name?'page':undefined" :class="{active:tab===name}" @click="tab=name">{{name}}</button></nav><small>Platform decisions.<br>One calm control room.</small><a href="/api/method/logout">Sign out</a></aside><main><header class="page-heading"><div><span class="eyebrow">YOUR PLATFORM, THOUGHTFULLY MANAGED</span><h1>{{tab==='Overview'?'Platform overview':tab}}</h1><p>Private owner workspace · {{session.user}}</p></div><button class="button subtle" :disabled="busy" @click="run(refresh)"><Icon name="RotateCcw" :size="16"/>Refresh</button></header><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status" class="form-note">{{note}}</p>
<template v-if="tab==='Overview'">
<p v-if="!loaded && busy" role="status">Loading platform overview…</p>
<div class="owner-metrics"><article v-for="(value,key) in summary" :key="key" class="panel"><span>{{labels[key] || key.replaceAll('_',' ')}}</span><strong>{{value}}</strong></article></div>
<section class="panel owner-block owner-attention"><div><span class="eyebrow">NEEDS YOUR ATTENTION</span><h2>Keep work moving</h2><p>Counts reflect records on this site. Open each queue to review its details.</p></div><div class="owner-queues"><button class="button subtle" @click="tab='Verification'">Provider approvals <strong>{{summary.pending_profiles ?? '—'}}</strong></button><button class="button subtle" @click="tab='Payouts'">Payout requests <strong>{{summary.pending_payouts ?? '—'}}</strong></button></div></section>
<div class="owner-actions"><button v-for="action in actions" :key="action.tab" class="panel owner-action" @click="tab=action.tab"><Icon :name="action.icon" :size="24"/><strong>{{action.title}}</strong><span>{{action.text}}</span><span class="owner-action-open">Open <Icon name="ArrowRight" :size="16"/></span></button></div>
</template>
<OwnerAccess v-else-if="tab==='Admin access'"/>
<SubscriptionAdmin v-else-if="tab==='Subscriptions'"/>
<section v-else-if="tab==='Verification'" class="panel owner-block"><h2>Provider verification</h2><p>Review each applicant before granting access. Institute approval grants administration of the specified workspace; each institute requires its own Frappe site.</p><label>Find an application<input v-model="search" type="search" placeholder="Name, username, provider type or country"></label><p>{{filtered.length}} of {{pending.length}} pending applications</p>
<article v-for="p in filtered" :key="p.name" class="owner-review owner-application"><div><strong>{{p.display_name}}</strong><p>@{{p.username}} · {{p.kind}} · {{p.country}}</p><label v-if="p.kind==='Institute'">Institute workspace record ID<input v-model="draft(p).workspace" placeholder="Configured IL Institute record on this site"></label><label>Review reason<textarea v-model="draft(p).reason" maxlength="1000" placeholder="Evidence reviewed and reason for this decision"></textarea></label></div><div class="owner-review-actions"><button class="button primary" :disabled="busy||!draft(p).reason.trim()||(p.kind==='Institute'&&!draft(p).workspace.trim())" @click="verify(p,'Verified')">Approve & issue code</button><button class="button subtle" :disabled="busy||!draft(p).reason.trim()" @click="verify(p,'Rejected')">Reject</button></div></article><p v-if="!pending.length && loaded">No profiles awaiting verification.</p><p v-else-if="pending.length && !filtered.length">No applications match your search.</p></section>
<GettingStarted v-else-if="tab==='Platform guide'" role="Super Admin"/><OnboardingSettings v-else-if="tab==='Signup & privacy'"/><Wallet v-else-if="tab==='Payouts'" :member="{role:'PlatformAdmin',user:session.user,name:session.user}"/>
</main></div></template>
<style>.owner-shell{min-height:100vh;background:rgb(108 106 238 / 4%);color:#44364f;display:grid;grid-template-columns:230px 1fr;--student-card:#fff;--student-ink:#44364f;--student-muted:#80718d;--student-border:rgb(108 106 238 / 8%);--student-soft:rgb(108 106 238 / 6%);--student-accent:#6C6AEE}.owner-shell aside{padding:38px 25px;background:#fffcff;border-right:1px solid rgb(108 106 238 / 8%);display:flex;flex-direction:column;gap:28px}.owner-tag{font-size:10px;letter-spacing:2px;color:#957cab}.owner-shell nav{display:grid;gap:8px}.owner-shell nav button{padding:15px;text-align:left;background:none;border:0;border-radius:12px;color:#766582;cursor:pointer}.owner-shell nav button.active{background:rgb(108 106 238 / 8%);color:#745294;font-weight:600}.owner-shell aside small{margin-top:auto;line-height:1.8;color:#8c7a99}.owner-shell aside>a:last-child{font-size:12px;color:#6C6AEE}.owner-shell main{padding:50px;min-width:0;max-width:1500px}.owner-shell h1{margin:12px 0}.owner-shell .page-heading p{font-size:12px}.owner-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.owner-metrics article{padding:25px}.owner-metrics span{font-size:12px;text-transform:capitalize;color:#8b7a98}.owner-metrics strong{display:block;font-size:36px;margin-top:15px}.owner-block{padding:30px;margin-top:25px}.owner-block p{font-size:13px;line-height:1.9;margin:15px 0}.owner-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.owner-block label{display:flex;flex-direction:column;gap:9px;font-size:12px}.owner-block :is(input,select,textarea){padding:13px;border-radius:10px;border:1px solid rgb(108 106 238 / 12%);background:rgb(108 106 238 / 4%);color:#53425f;min-width:0}.owner-calculator{padding:20px;background:rgb(108 106 238 / 6%);border-radius:16px;display:flex;gap:25px;align-items:center;margin-bottom:24px;flex-wrap:wrap}.owner-calculator strong{font-size:25px}.owner-calculator small{font-size:11px;flex-basis:100%}.owner-table{overflow:auto}.owner-table table{width:100%;font-size:12px;border-collapse:collapse}.owner-table :is(th,td){padding:15px;text-align:left;border-bottom:1px solid rgb(108 106 238 / 8%)}.owner-review{display:flex;align-items:center;gap:15px;padding:24px 0;border-bottom:1px solid rgb(108 106 238 / 8%)}.owner-review>div{flex:1}@media(max-width:800px){.owner-shell{display:block}.owner-shell aside{padding:18px}.owner-shell nav{display:flex;overflow:auto}.owner-shell aside small,.owner-tag{display:none}.owner-shell main{padding:24px}.owner-metrics{grid-template-columns:1fr 1fr}.owner-fields{grid-template-columns:1fr}.owner-review{flex-wrap:wrap}}
</style>

<style>
.owner-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:24px}.owner-action{padding:24px;text-align:left;display:flex;flex-direction:column;align-items:flex-start;gap:14px;color:inherit;cursor:pointer;font:inherit;border:1px solid #e8e2ef;background:#fff;border-radius:18px}.owner-action:hover{border-color:#7953ad;background:#fcfaff}.owner-action>span{font-size:13px;line-height:1.6;color:#786784}.owner-action .owner-action-open{display:flex;align-items:center;gap:8px;color:#57288b;margin-top:auto}.owner-shell button:focus-visible{outline:3px solid #a58bdb;outline-offset:3px}.owner-attention{display:flex;align-items:center;justify-content:space-between;gap:24px}.owner-queues{display:flex;flex-wrap:wrap;gap:12px}.owner-queues strong{background:#eee7f6;border-radius:8px;padding:4px 10px}.owner-application{align-items:flex-start}.owner-application label{margin-top:14px}.owner-review-actions{display:flex;flex-wrap:wrap;gap:10px;flex:0 1 210px!important}.owner-shell .owner-metrics{grid-template-columns:repeat(auto-fit,minmax(145px,1fr))}.owner-shell nav button{white-space:nowrap}.owner-shell .page-heading{flex-wrap:wrap;gap:16px}@media(max-width:1000px){.owner-actions{grid-template-columns:repeat(2,minmax(0,1fr))}.owner-attention{align-items:flex-start;flex-direction:column}}@media(max-width:540px){.owner-actions{grid-template-columns:1fr}.owner-shell main{padding:20px 14px}.owner-block{padding:20px}.owner-application{flex-direction:column}.owner-review-actions{flex:auto!important}}
</style>
